21		if err != nil {
22			t.Fatal(err)
23		}
24		now := e.Clock.Now()
25		if sub.Status != store.Active || !sub.CurrentPeriodStart.Equal(now) || !sub.CurrentPeriodEnd.Equal(now.AddDate(0, 1, 0)) {
26			t.Fatalf("subscription = %+v", sub)
27		}
28		invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
29		if len(invs) != 1 || invs[0].Status != store.InvoicePaid || invs[0].Lines[0].Quantity != 3 || invs[0].Lines[0].UnitAmount != 2000 {
30			t.Fatalf("invoices = %+v", invs)
31		}
32		if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 6000 {
33			t.Fatalf("charges = %+v", cs)
34		}
35	}
