// Package store keeps Tally's data in memory. It is safe for concurrent use.
//
// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
// tool, which act on behalf of the system rather than a member.
package store

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Errors. Callers check them with errors.Is; most are wrapped with a detail.
var (
	ErrNotFound      = errors.New("not found")
	ErrInvalid       = errors.New("invalid")
	ErrConflict      = errors.New("conflict")
	ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
	ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
	// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
	ErrCustomerOrgMismatch = errors.New("customer belongs to another organization")
)

// Store holds everything.
type Store struct {
	mu  sync.Mutex
	seq int

	orgs         map[string]Org
	users        map[string]User
	usersByEmail map[string]string // lower-case email -> user ID
	members      map[memberKey]Member
	apiKeys      map[string]APIKey
	keysByToken  map[string]string // token -> key ID
	invites      map[string]Invite

	customers        map[string]Customer
	customersByEmail map[string]string // lower-case email -> customer ID

	plans     map[string]Plan
	subs      map[string]Subscription
	usage     []UsageRecord
	invoices  map[string]Invoice
	payments  map[string]Payment
	endpoints map[string]WebhookEndpoint
	events    map[string]Event
	delivs    map[string]Delivery
}

type memberKey struct{ org, user string }

// New returns an empty store.
func New() *Store {
	return &Store{
		orgs: map[string]Org{}, users: map[string]User{}, usersByEmail: map[string]string{}, members: map[memberKey]Member{},
		apiKeys: map[string]APIKey{}, keysByToken: map[string]string{}, invites: map[string]Invite{},
		customers: map[string]Customer{}, customersByEmail: map[string]string{},
		plans: map[string]Plan{}, subs: map[string]Subscription{}, invoices: map[string]Invoice{}, payments: map[string]Payment{},
		endpoints: map[string]WebhookEndpoint{}, events: map[string]Event{}, delivs: map[string]Delivery{},
	}
}

// newID returns the next ID with the prefix, for example "cus_000042". The caller holds the lock.
func (s *Store) newID(prefix string) string {
	s.seq++
	return fmt.Sprintf("%s_%06d", prefix, s.seq)
}

// NewToken returns prefix followed by 32 random hex characters.
func NewToken(prefix string) string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return prefix + hex.EncodeToString(b)
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

func validEmail(email string) bool {
	at := strings.Index(email, "@")
	return at > 0 && at < len(email)-1 && !strings.ContainsAny(email, " \t\r\n,;<>")
}

func invalid(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalid, fmt.Sprintf(format, args...))
}

// ---- organizations

// CreateOrg adds an organization.
func (s *Store) CreateOrg(name string, plan OrgPlan, timeZone string, taxRateBP int, now time.Time) (Org, error) {
	o := Org{Name: strings.TrimSpace(name), Plan: plan, TimeZone: timeZone, TaxRateBP: taxRateBP, CreatedAt: now.UTC()}
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	o.ID = s.newID("org")
	s.orgs[o.ID] = o
	return o, nil
}

func checkOrg(o Org) error {
	if o.Name == "" {
		return invalid("an organization needs a name")
	}
	if !o.Plan.Valid() {
		return invalid("unknown plan %q", o.Plan)
	}
	if _, err := time.LoadLocation(o.TimeZone); err != nil || o.TimeZone == "" {
		return invalid("unknown time zone %q", o.TimeZone)
	}
	if o.TaxRateBP < 0 || o.TaxRateBP > 10000 {
		return invalid("the tax rate is 0 to 10000 basis points")
	}
	return nil
}

// Org returns an organization.
func (s *Store) Org(id string) (Org, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	return o, ok
}

// UpdateOrg changes an organization with f, which may refuse with an error.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
}

// ---- users and members

// CreateUser adds a user. Email addresses are unique, ignoring case.
func (s *Store) CreateUser(email, name string, now time.Time) (User, error) {
	email, name = strings.TrimSpace(email), strings.TrimSpace(name)
	if !validEmail(email) {
		return User{}, invalid("a user needs a valid email address")
	}
	if name == "" {
		return User{}, invalid("a user needs a name")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.usersByEmail[normEmail(email)]; ok {
		return User{}, ErrEmailTaken
	}
	u := User{ID: s.newID("usr"), Email: email, Name: name, CreatedAt: now.UTC()}
	s.users[u.ID] = u
	s.usersByEmail[normEmail(email)] = u.ID
	return u, nil
}

// User returns a user.
func (s *Store) User(id string) (User, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	return u, ok
}

// UserByEmail finds a user by email address, ignoring case.
func (s *Store) UserByEmail(email string) (User, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.usersByEmail[normEmail(email)]
	if !ok {
		return User{}, false
	}
	return s.users[id], true
}

// AddMember makes a user a member of an organization.
func (s *Store) AddMember(orgID, userID string, role Role, now time.Time) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.addMember(orgID, userID, role, now)
}

func (s *Store) addMember(orgID, userID string, role Role, now time.Time) (Member, error) {
	if _, ok := s.orgs[orgID]; !ok {
		return Member{}, ErrNotFound
	}
	if _, ok := s.users[userID]; !ok {
		return Member{}, ErrNotFound
	}
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; ok {
		return Member{}, ErrAlreadyMember
	}
	m := Member{OrgID: orgID, UserID: userID, Role: role, CreatedAt: now.UTC()}
	s.members[k] = m
	return m, nil
}

// Member returns a user's membership of an organization.
func (s *Store) Member(orgID, userID string) (Member, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	m, ok := s.members[memberKey{orgID, userID}]
	return m, ok
}

// Members returns an organization's members, oldest first.
func (s *Store) Members(orgID string) []Member {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Member{}
	for _, m := range s.members {
		if m.OrgID == orgID {
			out = append(out, m)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].UserID < out[j].UserID
	})
	return out
}

// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; !ok {
		return ErrNotFound
	}
	delete(s.members, k)
	return nil
}

// ---- API keys

// CreateAPIKey gives a member a new API key.
func (s *Store) CreateAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.createAPIKey(orgID, userID, name, now)
}

func (s *Store) createAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
	if _, ok := s.members[memberKey{orgID, userID}]; !ok {
		return APIKey{}, ErrNotFound
	}
	name = strings.TrimSpace(name)
	if name == "" {
		name = "API key"
	}
	k := APIKey{ID: s.newID("key"), OrgID: orgID, UserID: userID, Name: name, Token: NewToken("tly_"), CreatedAt: now.UTC()}
	s.apiKeys[k.ID] = k
	s.keysByToken[k.Token] = k.ID
	return k, nil
}

// APIKeyByToken finds the key a request presented. Revoked keys are returned too; the caller checks RevokedAt.
func (s *Store) APIKeyByToken(token string) (APIKey, bool) {
	if token == "" {
		return APIKey{}, false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.keysByToken[token]
	if !ok {
		return APIKey{}, false
	}
	return s.apiKeys[id], true
}

// APIKey returns one of an organization's keys.
func (s *Store) APIKey(orgID, id string) (APIKey, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || k.OrgID != orgID {
		return APIKey{}, false
	}
	return k, true
}

// APIKeys returns an organization's keys, oldest first.
func (s *Store) APIKeys(orgID string) []APIKey {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []APIKey{}
	for _, k := range s.apiKeys {
		if k.OrgID == orgID {
			out = append(out, k)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// RevokeAPIKey stops a key from working.
func (s *Store) RevokeAPIKey(orgID, id string, now time.Time) (APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || k.OrgID != orgID {
		return APIKey{}, ErrNotFound
	}
	if k.RevokedAt == nil {
		t := now.UTC()
		k.RevokedAt = &t
		s.apiKeys[id] = k
	}
	return k, nil
}

// TouchAPIKey records that a key was used.
func (s *Store) TouchAPIKey(id string, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if k, ok := s.apiKeys[id]; ok {
		t := now.UTC()
		k.LastUsedAt = &t
		s.apiKeys[id] = k
	}
}

// ---- invites

// CreateInvite invites an email address to join an organization with a role.
func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, ErrAlreadyMember
		}
	}
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
	s.invites[inv.ID] = inv
	return inv, nil
}

// Invite returns one of an organization's invites.
func (s *Store) Invite(orgID, id string) (Invite, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, false
	}
	return inv, true
}

// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
func (s *Store) Invites(orgID string) []Invite {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invite{}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// RevokeInvite withdraws an invite.
func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, ErrNotFound
	}
	if inv.RevokedAt == nil {
		t := now.UTC()
		inv.RevokedAt = &t
		s.invites[id] = inv
	}
	return inv, nil
}

// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
// makes them a member with the invite's role and gives them a first API key.
func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	var inv Invite
	found := false
	for _, i := range s.invites {
		if i.Token == token && token != "" {
			inv, found = i, true
			break
		}
	}
	if !found || inv.RevokedAt != nil {
		return User{}, Member{}, APIKey{}, ErrNotFound
	}
	var u User
	if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
		u = s.users[id]
	} else {
		name = strings.TrimSpace(name)
		if name == "" {
			return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
		}
		u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	t := now.UTC()
	inv.AcceptedAt = &t
	s.invites[inv.ID] = inv
	return u, m, k, nil
}
package store

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// ---- plans

// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
	p.Name = strings.TrimSpace(p.Name)
	if p.UsageType == "" {
		p.UsageType = Licensed
	}
	p.Active = true
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[p.OrgID]; !ok {
		return Plan{}, ErrNotFound
	}
	p.ID = s.newID("plan")
	p.CreatedAt = now.UTC()
	s.plans[p.ID] = p
	return p, nil
}

func checkPlan(p Plan) error {
	switch {
	case p.Name == "":
		return invalid("a plan needs a name")
	case !p.Currency.Valid():
		return invalid("unknown currency %q", p.Currency)
	case p.UnitAmount < 0:
		return invalid("a plan's price cannot be negative")
	case p.Interval != Monthly && p.Interval != Yearly:
		return invalid("a plan bills every month or every year")
	case p.UsageType != Licensed && p.UsageType != Metered:
		return invalid("a plan is licensed or metered")
	case p.TrialDays < 0 || p.TrialDays > 365:
		return invalid("a trial lasts 0 to 365 days")
	}
	return nil
}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return p, true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
// depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := old
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return p, nil
}

// ---- subscriptions

// CreateSubscription stores a new subscription. The caller sets its status and periods.
func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
		return Subscription{}, invalid("the discount is 0 to 100 percent")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.customers[sub.CustomerID]; !ok {
		return Subscription{}, ErrNotFound
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
		return Subscription{}, ErrNotFound
	}
	sub.ID = s.newID("sub")
	sub.CreatedAt = now.UTC()
	s.subs[sub.ID] = sub
	return copySub(sub), nil
}

// Subscription returns one of an organization's subscriptions.
func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[id]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, false
	}
	return copySub(sub), true
}

// SubscriptionFilter narrows Subscriptions.
type SubscriptionFilter struct {
	CustomerID string
	Status     SubStatus
}

// Subscriptions returns an organization's subscriptions that match f, oldest first.
func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
			continue
		}
		out = append(out, copySub(sub))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdateSubscription changes a subscription with f, which may refuse with an error.
func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	sub := copySub(old)
	if err := f(&sub); err != nil {
		return Subscription{}, err
	}
	sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	s.subs[id] = sub
	return copySub(sub), nil
}

// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
// canceled, the longest overdue first.
func (s *Store) DueSubscriptions(now time.Time) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
			out = append(out, copySub(sub))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
			return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

func copySub(sub Subscription) Subscription {
	if sub.TrialEnd != nil {
		t := *sub.TrialEnd
		sub.TrialEnd = &t
	}
	if sub.CanceledAt != nil {
		t := *sub.CanceledAt
		sub.CanceledAt = &t
	}
	return sub
}

// AddUsage records usage of a subscription to a metered plan at time at.
func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
	if quantity <= 0 {
		return UsageRecord{}, invalid("usage must be a positive quantity")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return UsageRecord{}, ErrNotFound
	}
	if p := s.plans[sub.PlanID]; p.UsageType != Metered {
		return UsageRecord{}, invalid("the subscription's plan is not metered")
	}
	u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
	s.usage = append(s.usage, u)
	return u, nil
}

// UsageTotal adds up a subscription's usage at times in [from, to).
func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	var n int64
	for _, u := range s.usage {
		if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
			n += u.Quantity
		}
	}
	return n
}

// ---- invoices

// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
	if !inv.Currency.Valid() {
		return Invoice{}, invalid("unknown currency %q", inv.Currency)
	}
	if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
		return Invoice{}, invalid("the discount is 0 to 100 percent")
	}
	for _, l := range inv.Lines {
		if l.Quantity <= 0 {
			return Invoice{}, invalid("a line needs a positive quantity")
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	org, ok := s.orgs[inv.OrgID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	c, ok := s.customers[inv.CustomerID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	if c.OrgID != inv.OrgID {
		return Invoice{}, ErrCustomerOrgMismatch
	}
	inv.ID = s.newID("in")
	inv.TaxRateBP = org.TaxRateBP
	inv.Status = InvoiceOpen
	inv.CreatedAt = now.UTC()
	inv.PaidAt, inv.VoidedAt = nil, nil
	inv = copyInvoice(inv)
	s.invoices[inv.ID] = inv
	return copyInvoice(inv), nil
}

// Invoice returns one of an organization's invoices.
func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	if !ok || inv.OrgID != orgID {
		return Invoice{}, false
	}
	return copyInvoice(inv), true
}

// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
func (s *Store) InvoiceByID(id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	return copyInvoice(inv), ok
}

// InvoiceFilter narrows ListInvoices.
type InvoiceFilter struct {
	CustomerID     string
	SubscriptionID string
	Status         InvoiceStatus
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	all := make([]Invoice, 0, len(s.invoices))
	for _, inv := range s.invoices {
		all = append(all, inv)
	}
	s.mu.Unlock()
	out := []Invoice{}
	for _, inv := range all {
		c := cloneInvoice(inv)
		if c.OrgID != orgID {
			continue
		}
		if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
			continue
		}
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.invoices[id]
	if !ok || old.OrgID != orgID {
		return Invoice{}, ErrNotFound
	}
	inv := copyInvoice(old)
	if err := f(&inv); err != nil {
		return Invoice{}, err
	}
	inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
	s.invoices[id] = copyInvoice(inv)
	return copyInvoice(inv), nil
}

// copyInvoice is a deep copy, so callers cannot change stored lines.
func copyInvoice(inv Invoice) Invoice {
	inv.Lines = append([]Line(nil), inv.Lines...)
	for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
		if *p != nil {
			t := **p
			*p = &t
		}
	}
	return inv
}

// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
func cloneInvoice(inv Invoice) Invoice {
	b, err := json.Marshal(inv)
	if err != nil {
		return copyInvoice(inv)
	}
	var out Invoice
	if err := json.Unmarshal(b, &out); err != nil {
		return copyInvoice(inv)
	}
	return out
}

// ---- payments

// CreatePayment records a payment attempt for one of the organization's invoices.
func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[p.InvoiceID]
	if !ok || inv.OrgID != p.OrgID {
		return Payment{}, ErrNotFound
	}
	if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
		return Payment{}, invalid("a payment succeeded or failed")
	}
	p.ID = s.newID("pay")
	p.CreatedAt = now.UTC()
	s.payments[p.ID] = p
	return p, nil
}

// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
func (s *Store) Payments(orgID, invoiceID string) []Payment {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Payment{}
	for _, p := range s.payments {
		if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}
package store

import (
	"encoding/json"
	"time"

	"example.com/tally/internal/money"
)

// OrgPlan is the Tally plan an organization pays for.
type OrgPlan string

// Tally's own plans.
const (
	OrgFree     OrgPlan = "free"
	OrgTeam     OrgPlan = "team"
	OrgBusiness OrgPlan = "business"
)

// Valid reports whether p is a known plan.
func (p OrgPlan) Valid() bool { return p == OrgFree || p == OrgTeam || p == OrgBusiness }

// Org is a tenant: a company that bills its customers through Tally.
type Org struct {
	ID       string  `json:"id"`
	Name     string  `json:"name"`
	Plan     OrgPlan `json:"plan"`
	TimeZone string  `json:"time_zone"` // IANA name, for example "Europe/Berlin"
	// TaxRateBP is the tax rate charged on the organization's invoices, in basis points (1% = 100).
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

// User is a person who can sign in. A user can belong to several organizations.
type User struct {
	ID        string    `json:"id"`
	Email     string    `json:"email"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
}

// Role is what a member may do in an organization.
type Role string

// Roles.
const (
	RoleOwner   Role = "owner"
	RoleAdmin   Role = "admin"
	RoleBilling Role = "billing"
	RoleMember  Role = "member"
	RoleViewer  Role = "viewer"
)

// Valid reports whether r is a known role.
func (r Role) Valid() bool {
	switch r {
	case RoleOwner, RoleAdmin, RoleBilling, RoleMember, RoleViewer:
		return true
	}
	return false
}

// Member is a user's membership of an organization.
type Member struct {
	OrgID     string    `json:"org_id"`
	UserID    string    `json:"user_id"`
	Role      Role      `json:"role"`
	CreatedAt time.Time `json:"created_at"`
}

// APIKey lets a member call the API. It acts as that member, with the member's current role.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Token      string     `json:"token"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Invite asks someone to join an organization. Its token is sent to the invited address.
type Invite struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	Email      string     `json:"email"`
	Role       Role       `json:"role"`
	Token      string     `json:"token"`
	InvitedBy  string     `json:"invited_by"`
	CreatedAt  time.Time  `json:"created_at"`
	AcceptedAt *time.Time `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Customer is one of an organization's customers.
type Customer struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	// DefaultPaymentMethod is charged for renewals ("pm_..."); empty means invoices wait to be paid by hand.
	DefaultPaymentMethod string            `json:"default_payment_method,omitempty"`
	Metadata             map[string]string `json:"metadata,omitempty"`
	CreatedAt            time.Time         `json:"created_at"`
}

// Interval is how often a plan bills.
type Interval string

// Intervals.
const (
	Monthly Interval = "month"
	Yearly  Interval = "year"
)

// UsageType says what a plan charges for.
type UsageType string

// Usage types.
const (
	// Licensed plans charge UnitAmount per seat (the subscription's quantity) at the start of each period.
	Licensed UsageType = "licensed"
	// Metered plans charge UnitAmount per unit of reported usage at the end of each period.
	Metered UsageType = "metered"
)

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	TrialDays  int            `json:"trial_days"`
	Active     bool           `json:"active"`
	CreatedAt  time.Time      `json:"created_at"`
}

// SubStatus is a subscription's state.
type SubStatus string

// Subscription states.
const (
	Trialing SubStatus = "trialing"
	Active   SubStatus = "active"
	PastDue  SubStatus = "past_due"
	Canceled SubStatus = "canceled"
)

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"

