// renew moves a subscription whose period ended on to its next period. It reports false, and no error, when the
// subscription was already moved on by another renewal.
//
// The period moves and its invoice is created in one step, which only happens while the subscription is still in the period
// it was read in. Only the renewal that made the invoice charges it, and the charge comes after the step, so a later renewal
// never finds a period it still has to invoice.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	dueEnd := sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		end := dueEnd
		x, _, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, func(x *store.Subscription) error {
