		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if inv == nil {
			x.Status = store.Active
		}
		return nil
	}, inv, now)
	if errors.Is(err, store.ErrStalePeriod) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
