					x.Status = st
				}
				return nil
			}); err != nil {
				return true, err
			}
		}
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", x)
	return true, payErr
}

// periodInvoice is the open invoice for one period of a subscription: a licensed plan bills its quantity, a metered plan the
// usage between start and end. It has no lines when there is nothing to bill.
func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// pay charges an invoice to the customer's default payment method. It reports false when the charge was declined. An invoice
// that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid here (it is
// paid by hand). When the gateway is unavailable it returns the error and the invoice stays open.
func (s *Service) pay(ctx context.Context, inv store.Invoice) (bool, error) {
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

// settle charges a renewal's invoice and reports the status the subscription has because of it: Active when the invoice was
// paid or has no payment method, PastDue when the charge was declined, and "" (keep the status) when the gateway was
// unavailable. Any other error is returned.
func (s *Service) settle(ctx context.Context, inv store.Invoice) (store.SubStatus, error) {
	paid, err := s.pay(ctx, inv)
	switch {
	case errors.Is(err, payments.ErrUnavailable):
		return "", nil
	case err != nil:
		return "", err
	case paid:
		return store.Active, nil
	default:
		return store.PastDue, nil
	}
}

