// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due; an unavailable gateway leaves the invoice open to be paid later, and the subscription keeps its status.
//
// RenewDue may run in several places at once, and again before an earlier run has finished: each subscription period is
// renewed and invoiced once. A subscription that another run has already moved on is skipped. A failing subscription does
// not stop the others; RenewDue returns the errors, joined, after trying them all. It returns how many subscriptions it
// renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew moves a subscription whose period has ended on to its next period. It reports false, and no error, when another
// renewal already moved the subscription on.
//
// The move and the invoice for the new period happen in one step, which only applies while the subscription is still in the
// period this renewal read. Only the renewal that created an invoice charges it, and it charges after the step, so no later
// renewal finds an unbilled period to bill again.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	dueEnd := sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		end := dueEnd
		x, _, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		}, nil, now)
		if errors.Is(err, store.ErrStalePeriod) {
			return false, nil
		}
		if err != nil {
			return false, err
		}
		s.publish(ctx, sub.OrgID, "subscription.canceled", x)
		return true, nil
	}

	start := now
	end := billing.AddInterval(start, plan.Interval)
	var inv *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		// Usage is billed in arrears, so the invoice is for the period that ended.
		p := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		inv = &p
	case plan.UsageType == store.Licensed:
		p := s.periodInvoice(sub, plan, start, end)
		inv = &p
	}
